import type { DataState } from '#UNSAFE_Collection';
import { getClientHints } from '#utils/PRIVATE_clientHints';
import { KEYS } from '#utils/PRIVATE_keyboardUtils';
import type { Item } from '#utils/UNSAFE_dataProvider';

/**
 * Helper function to determine whether the current device is a mobile device
 * @returns true if running on a mobile device, false otherwise
 */
export function isMobile() {
  const deviceType = getClientHints().deviceType;
  return deviceType === 'phone' || deviceType === 'tablet';
}

/**
 * Helper function to determine whether the current device is a phone
 * @returns true if running on a phone, false otherwise
 */
export function isPhone() {
  return getClientHints().deviceType === 'phone';
}

/**
 * Helper function to determine whether the current device is a tablet
 * @returns true if running on a tablet, false otherwise
 */
export function isTablet() {
  return getClientHints().deviceType === 'tablet';
}

export function isBeforeDataFetch<K, D>(data: DataState<K, D>) {
  return data.sizePrecision === 'atLeast' && data.totalSize === 0;
}

export function isSearchTextEmptyOrUndefined(searchText?: string) {
  return searchText === undefined || searchText.length === 0;
}

export function isSearchClearedFirstTime(prevSearchText?: string, searchText?: string) {
  return prevSearchText === undefined && searchText === '';
}

const LEGACY_IME_PROCESS_KEY_CODE = 229;

/**
 * JET-77501 - WHILE TYPING /SEARCHING JAPANESE CHARACTERS THE MENU DID NOT SHOW THE SUGGESTIONS FOR THE ENTERED VALUE
 * `event.isComposing` means the key event is still inside a composition session:
 * https://developer.mozilla.org/en-US/docs/Web/API/KeyboardEvent/isComposing
 * Common CJK IMEs compose text before commit. Apple documents Japanese conversion using
 * Space, arrow keys, and Return; Chinese/Cantonese candidate navigation using arrow keys
 * and Space or Return; and Korean Hanja candidates using arrow keys, Space, and Return.
 * Windows also exposes IME-specific virtual keys, including IME convert and accept keys.
 * https://support.apple.com/guide/japanese-input-method/keyboard-shortcuts-jpim10263/mac
 * https://support.apple.com/guide/chinese-input-method/use-the-candidate-window-cim12992/mac
 * https://support.apple.com/guide/korean-input-method/welcome/mac
 * https://learn.microsoft.com/en-us/windows/win32/inputdev/virtual-key-codes
 * If Select handles these keydown events while composing, it interferes with IME-owned
 * navigation and confirmation. Enter/NumpadEnter can be consumed by Select to commit or clear
 * the select value before the IME commits the composed text. Up/Down can be consumed by Select
 * to prevent default browser/IME behavior or move focus from the input into the select dropdown
 * while the user is still navigating IME candidates.
 */
export function shouldIgnoreSelectInputKeyDownDuringComposition(event: KeyboardEvent) {
  const isEnter = event.code === KEYS.ENTER || event.code === KEYS.NUMPAD_ENTER;
  const isArrow = event.code === KEYS.UP || event.code === KEYS.DOWN;
  // JET-77501 - WHILE TYPING /SEARCHING JAPANESE CHARACTERS THE MENU DID NOT SHOW THE SUGGESTIONS FOR THE ENTERED VALUE
  // Safari/WebKit requires an additional fallback for the Enter key that confirms an IME
  // candidate. Affected versions dispatch `compositionend` before that `keydown`, so the Enter
  // event incorrectly has `isComposing === false` and would otherwise reach Select's commit logic.
  // Those versions report `keyCode === 229` for the IME-owned event. Although `keyCode` is
  // deprecated, it is intentionally used only for this standards-API false negative:
  // https://developer.mozilla.org/en-US/docs/Web/API/KeyboardEvent/keyCode
  // https://bugs.webkit.org/show_bug.cgi?id=165004
  // WebKit records the event-ordering issue as fixed by the following bug, but the incorrect
  // behavior was still manually reproducible in Safari 26.5. A WebKit source change or backport
  // does not establish that a particular Safari release contains the effective fix. Remove this
  // fallback only after the behavior has been verified in every supported Safari version:
  // https://bugs.webkit.org/show_bug.cgi?id=311717
  // Do not gate the fallback using browser detection. Browser branding does not reliably identify
  // every WebKit host, including alternate browsers on iOS and embedded WKWebView applications.
  // In any browser, key code 229 identifies an IME-processed event, so Select should not treat that
  // Enter as a request to commit or clear its value.
  const isLegacyImeConfirmation =
    !event.isComposing && isEnter && event.keyCode === LEGACY_IME_PROCESS_KEY_CODE;

  return (event.isComposing && (isEnter || isArrow)) || isLegacyImeConfirmation;
}

/**
 * JET-77501 - WHILE TYPING /SEARCHING JAPANESE CHARACTERS THE MENU DID NOT SHOW THE SUGGESTIONS FOR THE ENTERED VALUE
 * `event.isComposing` means the key event is still inside a composition session:
 * https://developer.mozilla.org/en-US/docs/Web/API/KeyboardEvent/isComposing
 * Common CJK IMEs compose text before commit. Apple documents Japanese conversion using
 * Up/Down Arrow for kanji candidates, Chinese/Cantonese candidate navigation using arrow
 * keys, and Korean Hanja candidate navigation using arrow keys.
 * Windows also exposes IME-specific virtual keys, including IME convert and accept keys.
 * https://support.apple.com/guide/japanese-input-method/keyboard-shortcuts-jpim10263/mac
 * https://support.apple.com/guide/chinese-input-method/use-the-candidate-window-cim12992/mac
 * https://support.apple.com/guide/korean-input-method/welcome/mac
 * https://learn.microsoft.com/en-us/windows/win32/inputdev/virtual-key-codes
 * If Select handles these keyup events while composing, it interferes with IME-owned
 * candidate navigation. Up/Down can open the select dropdown, move focus into the dropdown,
 * or change Select's current row after the IME has used the same key to navigate candidates.
 */
export function shouldIgnoreSelectInputKeyUpDuringComposition(event: KeyboardEvent) {
  return event.isComposing && (event.code === KEYS.UP || event.code === KEYS.DOWN);
}

/**
 * Extract keys from a value items array.
 *
 * @param valueItems The value items from which the keys are to be extracted
 * @returns The set of keys
 */
export function createKeysFromValueItems<K, D>(valueItems?: Item<K, D>[]) {
  const keys = valueItems?.reduce((accumKeys, currentItem) => {
    accumKeys.add(currentItem.key);
    return accumKeys;
  }, new Set<K>());
  return keys;
}
